prompt:
Create unit `tasks` and implement `count_eq`: how many elements of `a` equal `v`, for arrays of at most 1_000_000 elements. The contract must state that the count lies between 0 and a.len(), and that it is 0 when no element equals v.

Required signature (in unit `tasks`):
fn count_eq(a: &[i64], v: i64) -> (r: i64)

reference.code:
spec fn len_ok(a: &[i64]) -> bool { a.len() <= 1000000 }

spec fn none_below(a: &[i64], v: i64, n: usize) -> bool { forall|k: usize| k < n ==> #[trigger] a[k] != v }

spec fn count_ok(a: &[i64], v: i64, n: usize, c: i64) -> bool { 0 <= c && c <= n && (none_below(a, v, n) ==> c == 0) }

spec fn is_count(a: &[i64], v: i64, r: i64) -> bool { 0 <= r && r <= a.len() && ((forall|k: usize| k < a.len() ==> #[trigger] a[k] != v) ==> r == 0) }

#[effects(pure)]
#[uses(len_ok, none_below, count_ok, is_count)]
fn count_eq(a: &[i64], v: i64) -> (r: i64)
    requires len_ok(a),
    ensures is_count(a, v, r),
{
    let mut c: i64 = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), count_ok(a, v, k, c),
        decreases a.len() - k,
    {
        if a[k] == v {
            c = c + 1;
        }
        k = k + 1;
    }
    c
}
